<section><h1><?= dts_escape($pageTitle) ?></h1><form method="post" action="<?= dts_escape($formAction) ?>" class="form-grid">
<label>First name<input name="firstname" maxlength="100" value="<?= dts_escape($user['firstname'] ?? '') ?>" required></label><label>Last name<input name="lastname" maxlength="100" value="<?= dts_escape($user['lastname'] ?? '') ?>" required></label><label>Middle name<input name="middlename" maxlength="100" value="<?= dts_escape($user['middlename'] ?? '') ?>"></label><label>Username<input name="username" maxlength="150" value="<?= dts_escape($user['username'] ?? '') ?>" required></label><label>Position title<input name="position_title" maxlength="100" value="<?= dts_escape($user['position_title'] ?? '') ?>"></label><label>Password<input type="password" name="password" maxlength="255" <?= empty($user) ? 'required' : '' ?>></label>
<?php if (empty($user) || !empty($canManageAccounts)): ?><label>Role<select name="role_id" required><?php foreach ($roles as $role): ?><option value="<?= dts_escape($role['role_id']) ?>" <?= (string)($user['role_id'] ?? '')===(string)$role['role_id']?'selected':'' ?>><?= dts_escape($role['role_name']) ?></option><?php endforeach; ?></select></label><label>Leader / Noted By<select name="leader_id"><option value="">None</option><?php foreach ($leaders as $leader): ?><option value="<?= dts_escape($leader['user_id']) ?>" <?= (string)($user['leader_id'] ?? '')===(string)$leader['user_id']?'selected':'' ?>><?= dts_escape(trim($leader['firstname'].' '.$leader['lastname'])) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<button type="submit">Save</button></form></section>
